/**
 * Test Case: Carts API
 *
 * Tags: @master @sanity @regression @api
 *
 * Covers prompts 20-28: get all, get by ID, date range, user carts, limit,
 * sort asc/desc, create, update and delete.
 */

// Generated by GitHub Copilot - Nov-23-2026
import { test, expect } from '@playwright/test';
import dotenv from 'dotenv';
import { Routes } from '../../api/endpoints/routes';
import { RandomDataUtil } from '../../utils/dataGenerator';

dotenv.config({ override: true });

test.describe('Carts API Tests', () => {

    // ---------------------------------------------------------
    // Configuration
    // ---------------------------------------------------------

    const BASE_URL = process.env.API_BASE_URL || Routes.BASE_URL;
    const CART_ID = Number(process.env.CART_ID ?? 1);
    const USER_ID = Number(process.env.USER_ID ?? 1);
    const LIMIT = Number(process.env.LIMIT ?? 3);
    const START_DATE = process.env.START_DATE as string;
    const END_DATE = process.env.END_DATE as string;

    // ---------------------------------------------------------
    // GET - Carts
    // ---------------------------------------------------------

    test('GET - All Carts @master @sanity @api', async ({ request }) => {
        const response = await request.get(`${BASE_URL}${Routes.GET_ALL_CARTS}`);

        expect(response.status(), 'Get all carts should return 200').toBe(200);

        const carts = await response.json();

        expect(Array.isArray(carts), 'Response should be an array').toBeTruthy();
        expect(carts.length, 'At least one cart should be returned').toBeGreaterThan(0);
        carts.forEach((cart: any) => {
            expect(typeof cart.id, 'Cart id should be a number').toBe('number');
            expect(typeof cart.userId, 'Cart userId should be a number').toBe('number');
            expect(Array.isArray(cart.products), 'Cart products should be an array').toBeTruthy();
        });
    });

    test('GET - Cart by ID @master @sanity @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_CART_BY_ID.replace('{id}', String(CART_ID))}`;
        const response = await request.get(url);

        expect(response.status(), 'Get cart by ID should return 200').toBe(200);

        const cart = await response.json();

        expect(cart.id, 'Returned cart ID should match the requested ID').toBe(CART_ID);
        expect(Array.isArray(cart.products), 'Cart products should be an array').toBeTruthy();
    });

    test('GET - Carts by Date Range @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_CARTS_BY_DATE_RANGE
            .replace('{startdate}', START_DATE)
            .replace('{enddate}', END_DATE)}`;
        const response = await request.get(url);

        expect(response.status(), 'Get carts by date range should return 200').toBe(200);

        const carts = await response.json();

        expect(Array.isArray(carts), 'Response should be an array').toBeTruthy();
        expect(carts.length, 'At least one cart should be in the date range').toBeGreaterThan(0);

        // The API returns ISO timestamps; compare only the YYYY-MM-DD part with the range.
        carts.forEach((cart: any) => {
            const cartDate = String(cart.date).split('T')[0];
            expect(cartDate >= START_DATE && cartDate <= END_DATE,
                `Cart ${cart.id} date ${cartDate} should be between ${START_DATE} and ${END_DATE}`).toBeTruthy();
        });
    });

    test('GET - User Carts @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_USER_CART.replace('{userId}', String(USER_ID))}`;
        const response = await request.get(url);

        expect(response.status(), 'Get user carts should return 200').toBe(200);

        const carts = await response.json();

        expect(Array.isArray(carts), 'Response should be an array').toBeTruthy();
        expect(carts.length, `User ${USER_ID} should have at least one cart`).toBeGreaterThan(0);
        carts.forEach((cart: any) => {
            expect(cart.userId, `Cart ${cart.id} should belong to user ${USER_ID}`).toBe(USER_ID);
        });
    });

    test('GET - Carts with Limit @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_CARTS_WITH_LIMIT.replace('{limit}', String(LIMIT))}`;
        const response = await request.get(url);

        expect(response.status(), 'Get carts with limit should return 200').toBe(200);

        const carts = await response.json();

        expect(Array.isArray(carts), 'Response should be an array').toBeTruthy();
        expect(carts.length, `Exactly ${LIMIT} carts should be returned`).toBe(LIMIT);
    });

    test('GET - Carts Sorted Ascending @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_CARTS_SORTED.replace('{order}', 'asc')}`;
        const response = await request.get(url);

        expect(response.status(), 'Get carts sorted ascending should return 200').toBe(200);

        const ids: number[] = (await response.json()).map((cart: any) => cart.id);
        const expectedIds = [...ids].sort((a, b) => a - b);

        expect(ids.length, 'Sorted list should not be empty').toBeGreaterThan(0);
        expect(ids, 'Cart IDs should be in ascending order').toEqual(expectedIds);
    });

    test('GET - Carts Sorted Descending @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_CARTS_SORTED.replace('{order}', 'desc')}`;
        const response = await request.get(url);

        expect(response.status(), 'Get carts sorted descending should return 200').toBe(200);

        const ids: number[] = (await response.json()).map((cart: any) => cart.id);
        const expectedIds = [...ids].sort((a, b) => b - a);

        expect(ids.length, 'Sorted list should not be empty').toBeGreaterThan(0);
        expect(ids, 'Cart IDs should be in descending order').toEqual(expectedIds);
    });

    // ---------------------------------------------------------
    // POST - Create Cart
    // ---------------------------------------------------------

    test('POST - Create Cart @master @regression @api', async ({ request }) => {
        const payload = RandomDataUtil.generateCartPayload(USER_ID);

        const response = await request.post(`${BASE_URL}${Routes.CREATE_CART}`, { data: payload });

        expect(response.status(), 'Create cart should return 201').toBe(201);

        const created = await response.json();

        expect(typeof created.id, 'A numeric cart ID should be returned').toBe('number');
        expect(created.userId, 'Cart should belong to the submitted user').toBe(USER_ID);
        expect(created.products, 'Cart products should match the submitted products').toEqual(payload.products);
    });

    // ---------------------------------------------------------
    // PUT - Update Cart
    // ---------------------------------------------------------

    test('PUT - Update Cart @master @regression @api', async ({ request }) => {
        // Read the current cart so the update is guaranteed to change a quantity.
        const getUrl = `${BASE_URL}${Routes.GET_CART_BY_ID.replace('{id}', String(CART_ID))}`;
        const current = await (await request.get(getUrl)).json();
        const originalQuantity: number = current.products[0].quantity;

        const payload = RandomDataUtil.generateUpdatedCartPayload(current.userId);
        payload.products = [{ productId: current.products[0].productId, quantity: originalQuantity + 1 }];

        const url = `${BASE_URL}${Routes.UPDATE_CART.replace('{id}', String(CART_ID))}`;
        const response = await request.put(url, { data: payload });

        expect(response.status(), 'Update cart should return 200').toBe(200);

        const updated = await response.json();

        expect(updated.id, 'Returned cart ID should match the requested ID').toBe(CART_ID);
        expect(updated.products, 'Cart products should reflect the update').toEqual(payload.products);
        expect(updated.products[0].quantity, 'Product quantity should have changed').not.toBe(originalQuantity);
    });

    // ---------------------------------------------------------
    // DELETE - Delete Cart
    // ---------------------------------------------------------

    test('DELETE - Delete Cart @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.DELETE_CART.replace('{id}', String(CART_ID))}`;

        const response = await request.delete(url);

        expect(response.status(), 'Delete cart should return 200').toBe(200);

        // For an existing cart the API returns the deleted record.
        const deleted = await response.json();
        expect(deleted.id, 'Deleted cart ID should match the requested ID').toBe(CART_ID);
    });
});
